(13, 'session-timeout', 1, 'index', 1, 1, '<div class="content_block">\r\n<p>Vypr&scaron;ela platnost přihl&aacute;&scaron;en&iacute;, byl(a) jste automaticky odhl&aacute;&scaron;en(a).</p>\r\n</div>\r\n<script type="text/javascript">// <![CDATA[\r\n showLoginForm();\r\n// ]]></script>'),
(14, 'session-timeout', 2, 'index', 1, 1, '<p>Session timeout elapsed, you were logged out automatically.</p>\r\n<script type="text/javascript"> showLoginForm(); </script>'),
(15, 'session-timeout', 16, 'index', 1, 1, '<p>Vypr&scaron;ela platnosť prihl&aacute;&scaron;en&iacute;, byl(a) jste automaticky odhl&aacute;&scaron;en(a).</p>\r\n<script type="text/javascript"> showLoginForm(); </script>'),
(16, 'terms-of-service', 1, 'terms-of-service', 2, 1, '<p>V&aacute;žen&iacute; obchodn&iacute; partneři,</p>\r\n<p>poskytneme V&aacute;m možnost podnikat na trhu kurzov&eacute;ho s&aacute;zen&iacute; bez rizika.</p>\r\n<p>Benefity a z&aacute;ruky:</p>\r\n<ul style="list-style-type: circle;">\r\n<li> <strong>Velmi n&iacute;zk&eacute; vstupn&iacute; n&aacute;klady pro podnik&aacute;n&iacute; v kurzov&eacute;m s&aacute;zen&iacute; </strong>-&nbsp; vybaven&iacute; s&aacute;zkov&eacute; kancel&aacute;ře,      pro&scaron;kolen&iacute; obsluhy, vyř&iacute;zen&iacute; požadovan&yacute;ch administrativn&iacute;ch &uacute;konů ve      vztahu ke st&aacute;tn&iacute;m instituc&iacute;m a přes internetov&eacute; připojen&iacute; formou &bdquo;on-line&ldquo;      V&aacute;m budeme zprostředkov&aacute;vat samotnou hru.</li>\r\n</ul>\r\n<ul>\r\n</ul>'),
(17, 'terms-of-service', 2, 'terms-of-service', 2, 1, '<p>Text defining the actual terms of service: bla bla bla bla bla blabla.....</p>'),
(18, 'terms-of-service', 16, 'terms-of-service', 2, 1, '<p>Text obchodn&iacute;ch podm&iacute;nek, bla bla bla bla bla blabla..... (SK)</p>'),
(19, 'promo-play', 1, 'promo-play', 1, 1, 'promo page to be made by marketing - CS'),
