(28, 'cooperation', 1, 'index', 1, 1, '<div class="content_block">\r\n<p>V&aacute;žen&iacute; obchodn&iacute; partneři,</p>\r\n<p><strong>poskytneme V&aacute;m možnost podnikat </strong>na trhu kurzov&eacute;ho s&aacute;zen&iacute; bez jak&yacute;chkoliv znalost&iacute; dan&eacute;ho oboru, bez zdlouhav&eacute;ho z&iacute;sk&aacute;v&aacute;n&iacute; praxe a zku&scaron;enost&iacute;. A hlavně <strong>bez rizika.</strong></p>\r\n<div class="line_separator_top">&nbsp;</div>\r\n<div id="about_us_helper">\r\n<div class="about_us_block">\r\n<h3>Benefity a z&aacute;ruky:</h3>\r\n<ul>\r\n<li>finančn&iacute; s&iacute;la a stabilita společnosti Victoria-Tip, a.s.</li>\r\n<li>přes 240 poboček po cel&eacute; Česk&eacute; republice</li>\r\n<li>neust&aacute;le se rozv&iacute;jej&iacute;c&iacute; s&aacute;zkov&aacute; kancel&aacute;ř</li>\r\n</ul>\r\n</div>\r\n<div class="about_us_block">\r\n<h3>Co potřebujete Vy jako provozovatel s&aacute;zkov&eacute; kancel&aacute;ře:</h3>\r\n<ul>\r\n<li>(pod)n&aacute;jemn&iacute; smlouvu k objektu, ve kter&eacute;m chcete pobočku provozovat</li>\r\n<li>v př&iacute;padě podn&aacute;jmu souhlas vlastn&iacute;ka nemovitosti</li>\r\n<li>v&yacute;pis z obchodn&iacute;ho rejstř&iacute;ku a osvědčen&iacute; o registraci</li>\r\n<li>internetov&eacute; připojen&iacute;</li>\r\n</ul>\r\n</div>\r\n</div>\r\n<div class="line_separator_top">&nbsp;</div>\r\n<div class="about_us_block">\r\n<h3>M&aacute;te z&aacute;jem o zř&iacute;zen&iacute; pobočky Victoria-Tip?</h3>\r\n<p>V souč&aacute;sn&eacute; době hled&aacute;me partnery pro zř&iacute;zen&iacute; nov&yacute;ch poboček po cel&eacute;m &uacute;zem&iacute; ČR.</p>\r\n<p>V nejbliž&scaron;&iacute; době se V&aacute;m ozvou na&scaron;i region&aacute;ln&iacute; manažeři s bliž&scaron;&iacute; nab&iacute;dkou.</p>\r\n<p>V př&iacute;padě z&aacute;jmu volejte na na&scaron;i  <strong>klientskou infolinku</strong> nebo n&aacute;s kontaktujte <strong>dal&scaron;&iacute;mi uveden&yacute;mi způsoby</strong>.</p>\r\n</div>\r\n<div class="about_us_block">\r\n<div id="about_us_contacts">\r\n<div class="about_us_contact">\r\n<table>\r\n<tbody>\r\n<tr>\r\n<td><img src="/images/telephone_icon.png" alt="" /></td>\r\n<td><span class="ico_content_cell">277 277 900</span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n<div class="about_us_contact">\r\n<table>\r\n<tbody>\r\n<tr>\r\n<td><img src="/images/email_icon.png" alt="" /></td>\r\n<td><span class="ico_content_cell">info@compbet.com</span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n<div class="about_us_contact">\r\n<table>\r\n<tbody>\r\n<tr>\r\n<td><img src="/images/form_icon.png" alt="" /></td>\r\n<td><span class="ico_content_cell">Nebo vyplňte on-line registračn&iacute; formul&aacute;ř <a href="/cs/registrace-poskytovatele">ZDE</a> </span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n</div>\r\n<p>Děkujeme</p>\r\n<p>&nbsp;</p>\r\n<div class="line_separator_bottom">&nbsp;</div>\r\n</div>'),
