(34, 'game-rules', 1, 'index', 1, 1, '<div class="content_block">\r\n<p><strong>Hern&iacute; pl&aacute;n pro s&aacute;zen&iacute; na pobočce:</strong></p>\r\n<p>-&nbsp;<a href="/pdf/hp_pobocky_2013_01_03.pdf" target="_blank">ve form&aacute;tu .pdf</a></p>\r\n<p>&nbsp;</p>\r\n<p><strong>Hern&iacute; pl&aacute;n pro s&aacute;zen&iacute; na internetu:</strong></p>\r\n<p>-&nbsp;<a href="/pdf/hp_internet_live_2011_10_10.pdf" target="_blank">ve form&aacute;tu .pdf</a></p>\r\n<p>&nbsp;</p>\r\n<p><strong>V&scaron;eobecn&eacute; podm&iacute;nky věrnostn&iacute;ho programu:</strong></p>\r\n-&nbsp;<a href="/pdf/vernostni-program.pdf" target="_blank">ve form&aacute;tu .pdf</a>\r\n<p>&nbsp;</p>\r\n</div>'),
